// The month the spend read covers, from the first of this month.
const now = new Date();
const monthStart = new Date(now.getFullYear(), now.getMonth(), 1).toISOString();
return [{ json: { monthStart } }];

// Groups this month's workflow_runs by agent. "Fetch spend rows" read them
// over the stored Supabase credential; this node used to fetch them itself
// with the service-role key written into its source (moved 2026-10-03).
const monthStart = $('Spend window').first().json.monthStart;
const runs = $input.first().json.body;

const allRuns = Array.isArray(runs) ? runs : [];

// Group by agent
const byAgent = {};
for (const run of allRuns) {
  const agent = run.agent_id || 'unknown';
  if (!byAgent[agent]) {
    byAgent[agent] = { totalCost: 0, totalApiCalls: 0, runs: 0, outcomes: {}, totalOutcomeCount: 0 };
  }
  byAgent[agent].totalCost += (run.cost_usd || 0);
  byAgent[agent].totalApiCalls += (run.api_calls || 0);
  byAgent[agent].runs++;
  byAgent[agent].totalOutcomeCount += (run.outcome_count || 0);

  const outcome = run.outcome || 'unknown';
  if (!byAgent[agent].outcomes[outcome]) byAgent[agent].outcomes[outcome] = 0;
  byAgent[agent].outcomes[outcome]++;
}

return [{ json: { byAgent, totalRuns: allRuns.length, monthStart } }];

// Adds the capability rows "Fetch budget rows" read over the stored Supabase
// credential (moved out of this node's source on 2026-10-03, with the
// service-role key).
const capabilities = $input.first().json.body;

const prevData = $('Fetch Spend Data').first().json;

return [{ json: { ...prevData, capabilities: Array.isArray(capabilities) ? capabilities : [] } }];

const data = $input.first().json;
const byAgent = data.byAgent || {};
const capabilities = data.capabilities || [];

const insights = [];
const recommendations = [];

// Build budget map from capabilities
const budgetMap = {};
const capsByAgent = {};
for (const cap of capabilities) {
  const agentId = cap.agent_id || cap.agent_name;
  if (!budgetMap[agentId]) {
    budgetMap[agentId] = cap.monthly_budget_usd || 0;
  } else {
    budgetMap[agentId] = Math.max(budgetMap[agentId], cap.monthly_budget_usd || 0);
  }
  if (!capsByAgent[agentId]) capsByAgent[agentId] = [];
  capsByAgent[agentId].push(cap);
}

// 1. Agents approaching budget limits (>80% used)
for (const [agent, info] of Object.entries(byAgent)) {
  const budget = budgetMap[agent] || 0;
  if (budget > 0) {
    const pct = (info.totalCost / budget) * 100;
    if (pct > 80) {
      insights.push({
        type: 'budget_warning',
        agent,
        detail: agent + ' has used $' + info.totalCost.toFixed(2) + ' of $' + budget.toFixed(2) + ' budget (' + pct.toFixed(1) + '%)',
        severity: pct > 100 ? 'critical' : 'warning'
      });
    }
  }
}

// 2. Cost per outcome metrics
for (const [agent, info] of Object.entries(byAgent)) {
  if (info.totalOutcomeCount > 0 && info.totalCost > 0) {
    const costPerOutcome = info.totalCost / info.totalOutcomeCount;
    insights.push({
      type: 'cost_per_outcome',
      agent,
      detail: agent + ': $' + costPerOutcome.toFixed(4) + ' per outcome (' + info.totalOutcomeCount + ' outcomes, $' + info.totalCost.toFixed(2) + ' total)',
      severity: 'info'
    });
  }
}

// 3. Free tier / unused capacity
for (const cap of capabilities) {
  const agentId = cap.agent_id || cap.agent_name;
  if (cap.is_active && (cap.monthly_spend_usd || 0) === 0 && (cap.monthly_budget_usd || 0) > 0) {
    recommendations.push({
      type: 'free_capacity',
      agent: agentId,
      api: cap.api_name || cap.capability_name || '',
      detail: 'Budget allocated but zero spend - free capacity available'
    });
  }
}

// 4. Model tiering suggestions
for (const [agent, info] of Object.entries(byAgent)) {
  if (info.totalCost > 5) {
    recommendations.push({
      type: 'model_tiering',
      agent,
      detail: 'Consider using Haiku for simple tasks, Sonnet for moderate tasks, and Opus only for complex reasoning to reduce costs'
    });
  }
}

return [{ json: { insights, recommendations, byAgent, totalRuns: data.totalRuns, capabilities } }];

// One item per capability row to update with this month's spend. "Write
// capability spend" sends each PATCH over the stored Supabase credential;
// this node used to send them itself with the service-role key written into
// its source (moved 2026-10-03). The report reads Cost Analysis directly.
const data = $input.first().json;
const byAgent = data.byAgent || {};
const capabilities = data.capabilities || [];

// Update monthly_spend_usd for each agent's capabilities
const patches = [];
for (const cap of capabilities) {
  const agentId = cap.agent_id || cap.agent_name;
  const agentData = byAgent[agentId];
  if (agentData && cap.id) {
    patches.push({ json: { id: cap.id, monthly_spend_usd: agentData.totalCost || 0 } });
  }
}

return patches;

const data = $input.first().json;
const insights = data.insights || [];
const recommendations = data.recommendations || [];
const byAgent = data.byAgent || {};

const lines = [
  '--- MindMaker Cost Advisor - Weekly Report ---',
  '',
  'Agent: Marcus',
  'Total workflow runs this month: ' + (data.totalRuns || 0),
  ''
];

// Spend by agent
lines.push('-- Spend by Agent --');
for (const [agent, info] of Object.entries(byAgent)) {
  lines.push('  ' + agent + ': $' + (info.totalCost || 0).toFixed(2) + ' (' + info.runs + ' runs, ' + info.totalApiCalls + ' API calls)');
}
lines.push('');

// Insights
if (insights.length > 0) {
  lines.push('-- Insights --');
  for (const i of insights) {
    lines.push('  [' + i.severity.toUpperCase() + '] ' + i.detail);
  }
  lines.push('');
}

// Recommendations
if (recommendations.length > 0) {
  lines.push('-- Recommendations --');
  for (const r of recommendations) {
    lines.push('  - ' + r.detail);
  }
}

if (insights.length === 0 && recommendations.length === 0) {
  lines.push('All agents operating within budget. No issues detected.');
}

const message = lines.join('\n');

return [{ json: { message, insightCount: insights.length, recommendationCount: recommendations.length } }];
